// --- Fields needed for menus + forms (adds TEAs & sections for tracker programs) ---
const PROGRAMS_FIELDS = [
  "id",
  "name",
  "displayName",
  "trackedEntityType",
  "programType",
  "organisationUnits[id,name,parent[id,name]]",

  // For tracker programs: TEAs needed for enrollment forms
  "programTrackedEntityAttributes[mandatory,trackedEntityAttribute[id,name,formName,attributeValues[value,attribute[id,code,name]],valueType,optionSetValue,optionSet[id,name,code,options[id,name,code]]]]",
  // Optional sectioning for TEAs
  "programSections[id,name,formName,trackedEntityAttributes[id,name,formName,valueType,attributeValues[value,attribute[id,code,name]],optionSetValue,optionSet[id,name,code,options[id,name,code]]]]",

  // For event & tracker-event forms: stages + their sections/DEs
  "programStages[id,name,displayName,programStageSections[id,name,programStage[id,name],formName,dataElements[id,name,sortOrder,formName,domainType,valueType,optionSetValue,attributeValues[value,attribute[id,code,name]],optionSet[id,name,code,options[id,name,code]]]],programStageDataElements[id,compulsory,programStage[id],dataElement[id,name,code,domainType,formName,valueType,optionSetValue,attributeValues[value,attribute[id,code,name]],optionSet[id,name,code,options[id,name,code]]]]]",
  "programRules[id,name,displayName,description,condition,priority,programRuleActions[id,programRuleActionType,dataElement[id,name,valueType],trackedEntityAttribute[id,name,valueType],data,content,location,programStageSection[id,name],programStage[id,name]]]",
  "programRuleVariables[id,name,displayName,programRuleVariableSourceType,useCodeForOptionSet,dataElement[id,name,valueType,optionSet[id]],trackedEntityAttribute[id,name,valueType,optionSet[id]],programStage[id,name]]",

  // NEW: required for grouping + ordering in navigation
  "attributeValues[value,attribute[id,code,name]]",
].join(",");

const PROGRAM_RULES_FIELDS =
  "id,name,displayName,description,condition,priority,program[id,name]," +
  "programRuleActions[id,programRuleActionType,dataElement[id,name,valueType],trackedEntityAttribute[id,name,valueType],data,content,location,programStageSection[id,name],programStage[id,name]]";

// --- Heavy fields for a single program drill (unchanged) ---
const PROGRAM_STAGES_FIELDS =
  "id,name,displayName,programType,attributeValues[value,attribute[id,code,name]]," +
  "programStages[id,name,displayName,formType,program[id,formType,programType]," +
  "programStageDataElements[id,compulsory,programStage[id]," +
  "dataElement[id,name,formName,displayName,code,valueType,domainType,attributeValues[value,attribute[id,code,name]],optionSetValue," +
  "optionSet[id,name,code,options[id,name,code]]]]," +
  "programStageSections[id,name,description,program[id,programType,formType]," +
  "programStage[id,name]," +
  "dataElements[id,name,formName,displayName,code,valueType,domainType,attributeValues[value,attribute[id,code,name]],optionSetValue," +
  "optionSet[id,name,code,options[id,name,code]]],sortOrder]]";

// --- keep these (referenced elsewhere) ---
const USER_ORGANISATION_UNITS =
  "userOnly=true&fields=id,name,code,level,parent(id,name,level,code),displayName&paging=false";

const ORGANISATION_UNITS_DESCENDANTS =
  "fields=id,name,code,level,displayName,parent[id,name,code,level,displayName],children[id,name,code,level,displayName]&paging=false";

// src/dhis2/dataStoreInit.js

const dataStoreInit = async (forceRefresh = false) => {
  try {
    // Check for cached data (unless forcing refresh)
    if (!forceRefresh) {
      const cachedData = await LocalForageService.getItem("dataStore", "dataStore");
      if (cachedData && Object.keys(cachedData).length > 0) {
        console.log("DataStore loaded from cache");
        return null;
      }
    }

    console.log("Fetching DataStore from API...");
    const namespaces = await dataStore.get("dataStore");

    // If "memis" namespace exists
    if (Array.isArray(namespaces?.data) && namespaces?.data?.includes("memis")) {
      const keys = await dataStore.get("dataStore/memis?fields=.&paging=false");

      const results = {};

      // Fetch all keys inside memis namespace
      if (Array.isArray(keys?.data?.entries)) {
        for (const key of keys?.data?.entries) {
          // const value = await dataStore.get(`dataStore/memis/${key}`);
          results[key?.key] = key?.value;
        }
      }

      // Store final object to LocalForage
      await LocalForageService.setItem(
        "dataStore",
        results,
        "dataStore"
      );
      console.log("DataStore initialized and cached");
      return null;
    }

    // "memis" namespace missing → ensure LocalForage still gets empty structure
    await LocalForageService.setItem("dataStore", {}, "dataStore");
    console.log("DataStore initialized but 'memis' namespace missing");
    return null;
  } catch (error) {
    console.log("DataStore initialization failed:", error);
    return error;
  }
};

