// import dataStore from "../services/Store/index";
// import LocalForageServiceInstance from "../utils/storage/LocalForageService";


const STORE_NAME = "metadata";
const OPTION_SETS_KEY = "optionSets";

/**
 * Initialize and cache DHIS2 metadata.
 */
const metadataInit = async (forceRefresh = false) => {
  try {
    if (!forceRefresh) {
      const cachedOptionSets =
        await LocalForageService.getItem(
          OPTION_SETS_KEY,
          STORE_NAME
        );

      if (Array.isArray(cachedOptionSets)) {
        console.log(
          "Metadata loaded from cache:",
          cachedOptionSets.length,
          "optionSets"
        );

        return null;
      }
    }

    console.log("Fetching metadata from API...");

    const response = await dataStore.get(
      "optionSets?fields=id,name,code,options[id,code,name]&paging=false"
    );

    const optionSets = response?.data?.optionSets || [];

    await LocalForageService.setItem(
      OPTION_SETS_KEY,
      optionSets,
      STORE_NAME
    );

    console.log(
      "Metadata initialized and cached:",
      optionSets.length,
      "optionSets"
    );

    return null;

  } catch (error) {
    console.error("Metadata initialization failed:", error);
    return error;
  }
};

const getAllOptionSetsFromCache = async () => {
  try {
    const optionSets = await LocalForageService.getItem(
      OPTION_SETS_KEY,
      STORE_NAME
    );

    return Array.isArray(optionSets) ? optionSets : [];
  } catch (error) {
    console.error("Error getting all optionSets:", error);
    return [];
  }
};

// src/dhis2/metadataInit.js

/**
 * Initialize and cache DHIS2 metadata (Programs, etc.)
 * This runs once on login to cache frequently accessed metadata
 */
const programsMetadata = async (forceRefresh = false) => {
  try {
    // Check if we already have cached metadata (unless forcing refresh)
    if (!forceRefresh) {

      const cachedPrograms = await LocalForageService.getItem("programs", "programs");
      if (cachedPrograms && Array.isArray(cachedPrograms) && cachedPrograms.length > 0) {
        console.log("Programs loaded from cache:", cachedPrograms.length, "programs");
        // return cachedPrograms;
        return null;
      }
    }

    console.log("Fetching programs from API...");
    const encodeFields = (fields) => encodeURIComponent(fields || "");

    // Cache Programs
    // await LocalForageServiceInstance.setItem("Programs", Programs, "metadata");
    const programPayload = await dataStore.get(
      `programs?fields=${encodeFields(PROGRAMS_FIELDS)}&paging=false`
    );
    const programs = programPayload?.data?.programs || [];

    const rulesPayload = await dataStore.get(
      `programRules?fields=${encodeFields(PROGRAM_RULES_FIELDS)}&paging=false`
    );

    const asArray = (p, key) =>
      Array.isArray(p?.[key]) ? p[key] : Array.isArray(p) ? p : [];

    const programList = asArray(programPayload?.data, "programs");
    const rulesList = asArray(rulesPayload?.data, "programRules");

    // Cache results
    await LocalForageService.setItem("programs", programList, "programs");
    await LocalForageService.setItem("programRules", rulesList, "programRules");

    console.log("Programs metadata initialized and cached:", programs.length, "programs");
    return null;

  } catch (error) {
    console.log("Metadata initialization failed:", error);
    return error;
  }
};

// src/dhis2/optionGroupsInit.js

/**
 * Initialize and cache DHIS2 optionGroups (optionGroups, etc.)
 * This runs once on login to cache frequently accessed optionGroups
 */
const optionsGroupsInit = async (forceRefresh = false) => {
  try {
    // Check if we already have cached optionGroups (unless forcing refresh)
    if (!forceRefresh) {
      const cachedoptionGroups = await LocalForageService.getItem("optionGroups", "optionGroups");
      if (cachedoptionGroups && Array.isArray(cachedoptionGroups) && cachedoptionGroups.length > 0) {
        console.log("optionGroups loaded from cache:", cachedoptionGroups.length, "optionGroups");
        return null;
      }
    }

    console.log("Fetching optionGroups from API...");

    // Fetch all optionGroups with their options
    const optionGroupsResponse = await dataStore.get(
      "optionGroups?fields=id,name,code,displayName,options[id,code,name,displayName]&paging=false"
    );

    const optionGroups = optionGroupsResponse?.data?.optionGroups || [];

    // Cache optionGroups
    await LocalForageService.setItem("optionGroups", optionGroups, "optionGroups");

    console.log("optionGroups initialized and cached:", optionGroups.length, "optionGroups");
    return null;

  } catch (error) {
    console.log("optionGroups initialization failed:", error);
    return error;
  }
};

// src/dhis2/orgUnitGroupsInit.js

/**
 * Initialize and cache DHIS2 orgUnitGroups (orgUnitGroups, etc.)
 * This runs once on login to cache frequently accessed orgUnitGroups
 */
const orgUnitGroupsInit = async (forceRefresh = false) => {
  try {
    // Check if we already have cached orgUnitGroups (unless forcing refresh)
    if (!forceRefresh) {
      const cachedorgUnitGroups = await LocalForageService.getItem(
        "orgUnitGroups",
        "orgUnitGroups",
      );
      if (
        cachedorgUnitGroups &&
        Array.isArray(cachedorgUnitGroups) &&
        cachedorgUnitGroups.length > 0
      ) {
        console.log(
          "orgUnitGroups loaded from cache:",
          cachedorgUnitGroups.length,
          "orgUnitGroups",
        );
        return null;
      }
    }

    console.log("Fetching orgUnitGroups from API...");

    // Fetch all orgUnitGroups with their options
    const orgUnitGroupsResponse = await dataStore.get(
      "organisationUnitGroups?fields=id,name,code,organisationUnits(id,name,code,level,parent(id,name,level,code))&paging=false",
    );

    const orgUnitGroups = orgUnitGroupsResponse?.data?.organisationUnitGroups || [];

    // Cache orgUnitGroups
    await LocalForageService.setItem(
      "orgUnitGroups",
      orgUnitGroups,
      "orgUnitGroups",
    );

    console.log(
      "orgUnitGroups initialized and cached:",
      orgUnitGroups.length,
      "orgUnitGroups",
    );
    return null;
  } catch (error) {
    console.log("orgUnitGroups initialization failed:", error);
    return error;
  }
};

