const renderListByUserRole = async ({ user, programId, orgUnit, params }) => {
  try {
    let res = null;

    const loggedInUserRoles = user?.userRoles || [];
    let listAccessRoles = await LocalForageService.getItem(
        "dataStore",
        "dataStore",
    );

    listAccessRoles = listAccessRoles?.viewAccessForTEI?.configurations?.find(
        (c) => c.program === programId,
    );

    const filterListByUser = listAccessRoles?.roles?.find((r) =>
        loggedInUserRoles?.some((ur) => ur.id === r?.id),
    );
    const hasFilter = filterListByUser?.hasFilter;
    const showOnlyAllocatedToMyWard = filterListByUser?.showOnlyAllocatedToMyWard;

    // orgUnit is sorted ascending by level — index 0 is the highest node in
    // the hierarchy. Using it with ouMode=DESCENDANTS ensures we see all TEIs
    // enrolled at any facility beneath it, matching what DHIS2 Capture shows.
    const topOrgUnit = orgUnit?.[0]?.id;
    if (topOrgUnit) {
      params?.append("orgUnit", topOrgUnit);
      params?.append("ouMode", "DESCENDANTS");
    }

    // Only restrict by TEI IDs when the role explicitly requires showing only
    // equipment allocated to the user's own ward. Roles that have hasFilter=true
    // but showOnlyAllocatedToMyWard=false (e.g. Biomedical Engineer) should see
    // the full list — filtering them by allocation event IDs would silently hide
    // any equipment that has never had an allocation event.
    if (hasFilter && showOnlyAllocatedToMyWard) {
      const listData = await dataStore.get(
          `tracker/events?program=${programId}&programStage=${filterListByUser?.filterStageId}&paging=false&fields=trackedEntity,createdAt,program,enrollment,programStage,orgUnit,dataValues[dataElement,value]`,
      );

      const userOrg =
          user?.organisationUnits?.sort((a, b) => a?.level - b?.level) || [];
      const myWardId = userOrg?.slice(-1)[0]?.id;

      const sortedEvents =
          listData?.data?.events?.sort(
              (a, b) => new Date(b.createdAt) - new Date(a.createdAt),
          ) || [];

      // Keep only the latest allocation event per trackedEntity
      const latestByTei = new Map();
      for (const ev of sortedEvents) {
        if (!latestByTei.has(ev.trackedEntity)) {
          latestByTei.set(ev.trackedEntity, ev);
        }
      }

      // Filter to only equipment whose latest allocation is to this user's ward
      // AND whose allocation event has been acknowledged (QUeq1Ulj7PG filled).
      // QUeq1Ulj7PG is the "Equipment recipient Status" field in the
      // Acknowledgement section — it is only written when the ward incharge
      // has confirmed physical receipt, which is the point at which equipment
      // counts as part of the ward's inventory.
      const ACKNOWLEDGEMENT_FIELD = "QUeq1Ulj7PG";
      const events = Array.from(latestByTei.values()).filter((ev) =>
          ev?.dataValues?.some(
              (dv) =>
                  dv?.dataElement === filterListByUser?.filterStageDataElementId &&
                  dv?.value === myWardId,
          ) &&
          ev?.dataValues?.some(
              (dv) =>
                  dv?.dataElement === ACKNOWLEDGEMENT_FIELD &&
                  dv?.value !== null &&
                  dv?.value !== undefined &&
                  dv?.value !== "",
          ),
      );

      const teiIds = events.map((e) => e?.trackedEntity);
      if (teiIds.length === 0) return;

      params?.append("trackedEntities", teiIds.join(","));
    }

    res = await dataStore.get(`tracker/trackedEntities?${params}`);
    return res;
  } catch (error) {
    console.log({ error });
  }
};

